var angDragDrop = angular.module("ang-drag-drop", []);

angDragDrop.directive("ngDrag", ["$parse", function($parse) {
    return {
        restrict: "A",
        link: function(scope, element, attrs) {
            var fn = $parse(attrs.ngDrag);
            element.on("dragstart", function(event) {
                var data = fn(scope);
                event.dataTransfer.setData("text", JSON.stringify(data));
                event.dataTransfer.effectAllowed = "move";
            });
        }
    };
}]);

angDragDrop.directive("ngDrop", ["$parse", function($parse) {
    return {
        restrict: "A",
        link: function(scope, element, attrs) {
            var fn = $parse(attrs.ngDrop);
            element.on("dragover", function(event) {
                event.preventDefault();
                event.dataTransfer.dropEffect = "move";
            });
            element.on("drop", function(event) {
                event.preventDefault();
                var data = JSON.parse(event.dataTransfer.getData("text"));
                fn(scope, { $data: data, $event: event });
            });
        }
    };
}]);